#!/usr/bin/env python
"""
Write backend/.env with a freshly generated SECRET_KEY.

Refuses to overwrite an existing file - rotating the key would invalidate every
issued session token, which is not something an installer should do silently.

    python backend/bootstrap_env.py
"""

import secrets
import sys
from pathlib import Path

TEMPLATE = """\
# Generated by install.bat. Do not commit this file.
SECRET_KEY={secret}
ALGORITHM=HS256
ACCESS_TOKEN_EXPIRE_MINUTES=1440
DATABASE_URL=sqlite:///./medassist.db

# Restrict this to your real frontend origin before deploying.
CORS_ORIGINS=http://localhost:5173,http://127.0.0.1:5173,http://localhost:8501,http://127.0.0.1:8501

LOGIN_RATE_LIMIT_ATTEMPTS=10
LOGIN_RATE_LIMIT_WINDOW_SECONDS=60

# Creates one admin account on first startup if no admin exists yet.
# CHANGE THIS PASSWORD before exposing the app to anyone.
BOOTSTRAP_ADMIN_EMAIL=admin@medassist.local
BOOTSTRAP_ADMIN_PASSWORD=ChangeMe123!
"""


def main() -> int:
    env_path = Path(__file__).resolve().parent / ".env"
    if env_path.exists():
        print(f"  {env_path.name} already exists - leaving it untouched.")
        return 0

    env_path.write_text(TEMPLATE.format(secret=secrets.token_hex(32)),
                        encoding="utf-8")
    print(f"  Wrote {env_path.name} with a freshly generated SECRET_KEY.")
    print("  NOTE: change BOOTSTRAP_ADMIN_PASSWORD before deploying anywhere real.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
